<?php
session_start(); if (!isset($_SESSION['usuario_id']) || $_SERVER['REQUEST_METHOD'] !== 'POST') { header('Location: login.php'); exit; } require_once 'conexao.php';
$emprestimoId=(int)($_POST['emprestimo_id']??0); $usuarioId=(int)$_SESSION['usuario_id']; mysqli_begin_transaction($conexao);
try { $stmt=mysqli_prepare($conexao,"SELECT livro_id FROM emprestimos WHERE id=? AND usuario_id=? AND status='Ativo' FOR UPDATE"); mysqli_stmt_bind_param($stmt,'ii',$emprestimoId,$usuarioId); mysqli_stmt_execute($stmt); $emprestimo=mysqli_fetch_assoc(mysqli_stmt_get_result($stmt)); if (!$emprestimo) throw new Exception('Empréstimo não encontrado.'); $stmt=mysqli_prepare($conexao,"UPDATE emprestimos SET status='Devolvido', data_devolucao=CURDATE() WHERE id=?"); mysqli_stmt_bind_param($stmt,'i',$emprestimoId); mysqli_stmt_execute($stmt); $stmt=mysqli_prepare($conexao,'UPDATE livros SET quantidade=quantidade+1 WHERE id=?'); mysqli_stmt_bind_param($stmt,'i',$emprestimo['livro_id']); mysqli_stmt_execute($stmt); mysqli_commit($conexao); $mensagem='Devolução registrada com sucesso.'; } catch (Throwable $e) { mysqli_rollback($conexao); $mensagem='Não foi possível registrar a devolução.'; }
header('Location: index.php?mensagem='.urlencode($mensagem));
